#include <stdio.h>
#include <stdlib.h>

#define INF 1000000000

typedef struct {
    int to, t, p, next;
} Edge;

typedef struct {
    int t, u, c;
} HeapNode;

typedef struct {
    HeapNode *arr;
    int size;
    int cap;
} Heap;

void heap_push(Heap *h, int t, int u, int c) {
    int i = h->size++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (h->arr[parent].t <= t) break;
        h->arr[i] = h->arr[parent];
        i = parent;
    }
    h->arr[i].t = t;
    h->arr[i].u = u;
    h->arr[i].c = c;
}

HeapNode heap_pop(Heap *h) {
    HeapNode res = h->arr[0];
    h->size--;
    if (h->size > 0) {
        HeapNode last = h->arr[h->size];
        int i = 0;
        while (1) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            if (left >= h->size) break;
            int child = left;
            if (right < h->size && h->arr[right].t < h->arr[left].t)
                child = right;
            if (h->arr[child].t >= last.t) break;
            h->arr[i] = h->arr[child];
            i = child;
        }
        h->arr[i] = last;
    }
    return res;
}

int main() {
    int V, N, M;
    if (scanf("%d %d %d", &V, &N, &M) != 3) return 0;

    int C = V + 1;

