    Edge *edges = (Edge *)malloc((2 * M) * sizeof(Edge));
    int ec = 0;

    for (int i = 0; i < M; i++) {
        int A, B, T, P;
        scanf("%d %d %d %d", &A, &B, &T, &P);

        edges[ec].to = B;
        edges[ec].t = T;
        edges[ec].p = P;
        edges[ec].next = head[A];
        head[A] = ec++;

        edges[ec].to = A;
        edges[ec].t = T;
        edges[ec].p = P;
        edges[ec].next = head[B];
        head[B] = ec++;
    }

    int X, Y;
    scanf("%d %d", &X, &Y);

    int totalStates = (N + 1) * C;
    int *dist = (int *)malloc(totalStates * sizeof(int));
    for (int i = 0; i < totalStates; i++) dist[i] = INF;

    int start = X * C + 0;
    dist[start] = 0;

    Heap h;
    h.cap = 2 * M * C + 5;
    h.arr = (HeapNode *)malloc(h.cap * sizeof(HeapNode));
    h.size = 0;

    heap_push(&h, 0, X, 0);

    int ans = -1;

    while (h.size > 0) {
        HeapNode cur = heap_pop(&h);
        int u = cur.u;
        int c = cur.c;
        int t = cur.t;

        int idx = u * C + c;
        if (t != dist[idx]) continue;

        if (u == Y) {
            ans = t;
            break;
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int nc = c + edges[e].p;
            if (nc > V) continue;

            int v = edges[e].to;
            int nt = t + edges[e].t;
            int nidx = v * C + nc;

            if (nt < dist[nidx]) {
                dist[nidx] = nt;
                heap_push(&h, nt, v, nc);
            }
        }
    }

    printf("%d\n", ans);

    free(head);
    free(edges);
    free(dist);
    free(h.arr);

    return 0;
}
